// <auto-generated/>
using System;
using System.Collections;
using System.Data;
using System.Text;

using DNAide.Core;
using DNAide.Data;
using DNAide.Utils;
using DNAide.Web;

using Sunplus.Accounting.Business.CacheManager;
using Sunplus.Accounting.Core.Common;
using Sunplus.Accounting.Core.Extensions;
using Sunplus.Accounting.Core.Web.Controls;
using Sunplus.Accounting.DataAccess;

namespace BLL.Report.NonePT
{
    public class NonePTMemSummaryManager : ReportBase
    {
        private string msg = "<span class='error-message'>{content}</span>";

        public string LoadHeader()
        {
            string header = TemplateHandler.LoadTemplate("Report/NonePT/NonePTHeader.htm");
            return header;
        }

        public override string RenderHTML(Hashtable input)
        {
            return string.Empty;
        }

        #region getNonePTMembers

        public string getNonePTMembers(string username, string currpage)
        {
            string tpl = TemplateHandler.LoadTemplate("Report/NonePT/NonePTContent.htm");
            string tplContent = TemplateHandler.CopyBlock(tpl, "content");
            string tplFooter = TemplateHandler.CopyBlock(tpl, "footer");
            string tplPaging = TemplateHandler.CopyBlock(tpl, "paging");
            var rows = new StringBuilder();
            int totalpages = 0;
            try
            {
                var param = new Hashtable();
                param.Add("username", username);
                param.Add("pagenum", currpage);
                param.Add("totalpages", 0);
                param.Add("errcode", 0);
                param.Add("errmsg", "");

                DbResult rs = IBCProvider.ReportProvider.NonePT().NonePTMemSummary(param);

                int errcode = CastAide.AsInt32(rs.Outputs["errcode"]);
                string errmsg = CastAide.AsString(rs.Outputs["errmsg"]);
                totalpages = CastAide.AsInt32(rs.Outputs["totalpages"]);

                if (errcode > 0)
                {
                    TemplateHandler.Assign(ref msg, "content", errmsg);
                    TemplateHandler.ReplaceBlock(ref tpl, "content",
                                                 "<tr><td colspan='9' class='c'>" + msg + "</td></tr>");
                    TemplateHandler.RemoveBlock(ref tpl, "footer");
                    TemplateHandler.RemoveBlock(ref tpl, "paging");
                }
                else
                {
                    var dt = new DataTable();
                    dt = rs.ResultSet.Tables[0];

                    if (dt != null)
                    {
                        SetCacheReport("accrptnoneptmemsummary." + AppSession.Username, dt, DateTime.Now.AddHours(5));
                    }
                    if (dt.Rows.Count == 0)
                    {
                        TemplateHandler.Assign(ref msg, "content", ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "thereisnodata"));
                        TemplateHandler.ReplaceBlock(ref tpl, "content",
                                                     "<tr><td colspan='9' class='c'>" + msg + "</td></tr>");
                        TemplateHandler.RemoveBlock(ref tpl, "footer");
                        TemplateHandler.RemoveBlock(ref tpl, "paging");
                    }
                    else
                    {
                        #region content

                        DataRow[] Rows = dt.Select();
                        int order = (CastAide.AsInt32(currpage) - 1) * 1000 + 1;
                        foreach (DataRow dr in Rows)
                        {
                            string row = tplContent;

                            TemplateHandler.Assign(ref row, "Order", NumberFormat.DecFormat(order, 0));
                            TemplateHandler.Assign(ref row, "Currency",
                                                   CacheUtils.GetExchangeName(CastAide.AsInt32(dr["currency"])));
                            TemplateHandler.Assign(ref row, "SuperName", dr["Super"]);
                            TemplateHandler.Assign(ref row, "MasterName", dr["Master"]);
                            TemplateHandler.Assign(ref row, "AgentName", dr["Agent"]);
                            TemplateHandler.Assign(ref row, "MemberName", dr["Member"]);
                            TemplateHandler.Assign(ref row, "BetCount", NumberFormat.DecFormat(dr["BetCount"], 0));
                            TemplateHandler.Assign(ref row, "RunningTOTotal",
                                                   NumberFormat.DecFormat(dr["RunningTOTotal"], 2));
                            TemplateHandler.Assign(ref row, "TOTotal", NumberFormat.DecFormat(dr["TOTotal"], 2));

                            rows.Append(row);
                            order++;
                        }

                        TemplateHandler.ReplaceBlock(ref tpl, "content", rows.ToString());
                        TemplateHandler.Assign(ref tplFooter, "BetCount",
                                               NumberFormat.DecFormat(dt.Compute("sum(BetCount)", ""), 0));
                        TemplateHandler.Assign(ref tplPaging, "paging",
                                               Pager.InitPager(totalpages, CastAide.AsInt32(currpage), ""));
                        TemplateHandler.ReplaceBlock(ref tpl, "footer", tplFooter);
                        TemplateHandler.ReplaceBlock(ref tpl, "paging", tplPaging);

                        #endregion content
                    }
                }
            }
            catch (Exception ex)
            {
                Sunplus.Accounting.Core.Extensions.LogExtensions.ExceptionHandler(ex);
                TemplateHandler.RemoveBlock(ref tpl, "footer");
                TemplateHandler.RemoveBlock(ref tpl, "paging");
                TemplateHandler.Assign(ref msg, "content", ex.Message);
                TemplateHandler.ReplaceBlock(ref tpl, "content", "<tr><td colspan='9' class='c'>" + msg + "</td></tr>");
            }

            return tpl;
        }

        #endregion getNonePTMembers
    }
}